mapper.select:
select count(1)
from contract c
left join contract_and_user ca on c.id = ca.contract_id and ca.status in (0, 1)
where ca.user_id = #{userId}
   or ca.signed_by = #{userId}

select count(1)
from contract c
left join contract_and_user ca on c.id = ca.contract_id and ca.status in (2, 3)
where ca.user_id = #{userId}
   or ca.signed_by = #{userId}

select c.*, u.user_name as userName,tb.user_name as signUserName,tc.user_name as copyUserName from contract c left join contract_and_user ca on c.id = ca.contract_id left join tb_user u on c.user_id = u.user_id left join tb_user tb on ca.signed_by = tb.user_id left join tb_user tc on ca.copy_user = tc.user_id where 1=1
and c.contract_name like concat('%',#{contract.contractName},'%')
and u.user_name like concat('%',#{contract.userName},'%')
and tb.user_name like concat('%',#{contract.signUserName},'%')
and tc.user_name like concat('%',#{contract.copyUserName},'%')
and c.type = #{contract.contractType}
and c.is_complete = #{contract.isComplete}
and c.draft_status = #{contract.draftStatus}
group by c.id order by c.create_time desc
